-- Equipment from Rifts Ultimate Edition, printed pp.261-270.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local  apps/character-creator/db/add-rue-equipment.sql
--   node scripts/d1-apply.mjs --remote apps/character-creator/db/add-rue-equipment.sql
--
-- Read out of the equipment chapter with the app's own gear importer, in four
-- batches split on the book's own section boundaries so each carried a correct
-- category and none straddled two kinds of thing.
--
-- 109 rows: everything staged that collides with nothing already in the
-- catalog. 27 further rows are deliberately NOT here.
--
-- WHY THE IMPORTER COULD NOT MATCH ANY OF THIS ITSELF. It derives a slug from
-- the book's name, and the book writes "Belt, Ammo (with six pouches; military
-- style)" where a class equipment list produced the stub `ammo-belt`. Inverted
-- word order plus a parenthetical qualifier misses every time, so all 158 rows
-- staged as inserts - including the ones that ARE catalog items - and
-- confirming them wholesale would have duplicated 27 existing rows and none of
-- the 84 stubs would have been filled.
--
-- THE 27 HELD BACK are three different problems wearing one shape, which is why
-- they are a review rather than a rule:
--
--   identical item, identical price   First-Aid Kit 100 = 100, Wastelander
--                                     Motorcycle 18000 = 18000. Nothing to add.
--   the book distinguishes what the   Knife Large vs Knife Small vs the
--   catalog flattened                 catalog's one `knife`; "Dead Boy" CA-1,
--                                     CA-2 and Black Market are three armours.
--   same item, price disagrees        Belt, Utility 3 -> 5; Survival Knife
--                                     120 -> 300. RUE is the later book, so
--                                     that is an update, not a second row.
--
-- INSERT OR IGNORE on a UNIQUE slug: re-running adds nothing and cannot
-- overwrite a row that already exists.

INSERT OR IGNORE INTO gear
  (slug, name, category, weight_lbs, cost, damage, is_mega_damage, range, payload, rate_of_fire, ar, mdc, description, system, source_book)
